private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixList = new ArrayList<>(bounds.size());
    long total = 0L;
    int n = bounds.size();
    int[] suffixArray = new int[n];
    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixArray[i] = (int) runningSum;
    }
    for (int i = 0; i < n; i++) {
        suffixList.add(suffixArray[i]);
    }
    for (int value : bounds) {
        total += value;
    }
    return new Pair<>(suffixList, total);
}

